// ---- layers ----
// conv1: conv3x3 (broadcast), one channel, int16 16x16 -> 14x14, ReLU, >> 4; SMLAD, 2 outputs per step
static inline void conv1_ch(const int16_t *restrict in, const uint32_t *restrict kp, int16_t *restrict out) {
    const uint32_t a0 = kp[0], a1 = kp[1], a2 = kp[2], b0 = kp[3], b1 = kp[4], b2 = kp[5];
    for (int y = 0; y < 14; y++) {
        const int16_t *row = in + y * 16;
        int16_t *o = out + y * 14;
        #pragma GCC unroll 1
        for (int x = 0; x < 14; x += 2) {
            int32_t s0, s1;
            {
                uint32_t p, q;
                memcpy(&p, row + 0 + x, 4);
                memcpy(&q, row + 0 + x + 2, 4);
                s0 = SMUAD(p, a0);
                s0 = SMLABT(q, b0, s0);
                s1 = SMUAD(q, b0);
                s1 = SMLATB(p, a0, s1);
            }
            {
                uint32_t p, q;
                memcpy(&p, row + 16 + x, 4);
                memcpy(&q, row + 16 + x + 2, 4);
                s0 = SMLAD(p, a1, s0);
                s0 = SMLABT(q, b1, s0);
                s1 = SMLAD(q, b1, s1);
                s1 = SMLATB(p, a1, s1);
            }
            {
                uint32_t p, q;
                memcpy(&p, row + 32 + x, 4);
                memcpy(&q, row + 32 + x + 2, 4);
                s0 = SMLAD(p, a2, s0);
                s0 = SMLABT(q, b2, s0);
                s1 = SMLAD(q, b2, s1);
                s1 = SMLATB(p, a2, s1);
            }
            uint32_t w = (uint32_t)USAT(s0 >> 4, 15) | ((uint32_t)USAT(s1 >> 4, 15) << 16);
            memcpy(o + x, &w, 4);
        }
    }
}

// dw1: conv3x3 (depthwise), one channel, int16 14x14 -> 12x12, ReLU, >> 4; SMLAD, 2 outputs per step
static inline void dw1_ch(const int16_t *restrict in, const uint32_t *restrict kp, int16_t *restrict out) {
    const uint32_t a0 = kp[0], a1 = kp[1], a2 = kp[2], b0 = kp[3], b1 = kp[4], b2 = kp[5];
    for (int y = 0; y < 12; y++) {
        const int16_t *row = in + y * 14;
        int16_t *o = out + y * 12;
        #pragma GCC unroll 1
        for (int x = 0; x < 12; x += 2) {
            int32_t s0, s1;
            {
                uint32_t p, q;
                memcpy(&p, row + 0 + x, 4);
                memcpy(&q, row + 0 + x + 2, 4);
                s0 = SMUAD(p, a0);
                s0 = SMLABT(q, b0, s0);
                s1 = SMUAD(q, b0);
                s1 = SMLATB(p, a0, s1);
            }
            {
                uint32_t p, q;
                memcpy(&p, row + 14 + x, 4);
                memcpy(&q, row + 14 + x + 2, 4);
                s0 = SMLAD(p, a1, s0);
                s0 = SMLABT(q, b1, s0);
                s1 = SMLAD(q, b1, s1);
                s1 = SMLATB(p, a1, s1);
            }
            {
                uint32_t p, q;
                memcpy(&p, row + 28 + x, 4);
                memcpy(&q, row + 28 + x + 2, 4);
                s0 = SMLAD(p, a2, s0);
                s0 = SMLABT(q, b2, s0);
                s1 = SMLAD(q, b2, s1);
                s1 = SMLATB(p, a2, s1);
            }
            uint32_t w = (uint32_t)USAT(s0 >> 4, 15) | ((uint32_t)USAT(s1 >> 4, 15) << 16);
            memcpy(o + x, &w, 4);
        }
    }
}

// pool1: maxpool 2x2, one channel, 12x12 -> 6x6
static inline void pool1_ch(const int16_t *restrict in, int16_t *restrict out) {
    for (int y = 0; y < 6; y++) {
        const int16_t *r0 = in + 2 * y * 12, *r1 = r0 + 12;
        for (int x = 0; x < 6; x++) {
            int32_t a = r0[2 * x], b = r0[2 * x + 1], c = r1[2 * x], d = r1[2 * x + 1];
            int32_t ab = a > b ? a : b, cd = c > d ? c : d;
            out[y * 6 + x] = ab > cd ? ab : cd;
        }
    }
}

// dw2: conv3x3 (depthwise), one channel, int16 6x6 -> 4x4, ReLU, >> 4; SMLAD, 2 outputs per step
static inline void dw2_ch(const int16_t *restrict in, const uint32_t *restrict kp, int32_t *restrict out) {
    const uint32_t a0 = kp[0], a1 = kp[1], a2 = kp[2], b0 = kp[3], b1 = kp[4], b2 = kp[5];
    for (int y = 0; y < 4; y++) {
        const int16_t *row = in + y * 6;
        int32_t *o = out + y * 4;
        #pragma GCC unroll 1
        for (int x = 0; x < 4; x += 2) {
            int32_t s0, s1;
            {
                uint32_t p, q;
                memcpy(&p, row + 0 + x, 4);
                memcpy(&q, row + 0 + x + 2, 4);
                s0 = SMUAD(p, a0);
                s0 = SMLABT(q, b0, s0);
                s1 = SMUAD(q, b0);
                s1 = SMLATB(p, a0, s1);
            }
            {
                uint32_t p, q;
                memcpy(&p, row + 6 + x, 4);
                memcpy(&q, row + 6 + x + 2, 4);
                s0 = SMLAD(p, a1, s0);
                s0 = SMLABT(q, b1, s0);
                s1 = SMLAD(q, b1, s1);
                s1 = SMLATB(p, a1, s1);
            }
            {
                uint32_t p, q;
                memcpy(&p, row + 12 + x, 4);
                memcpy(&q, row + 12 + x + 2, 4);
                s0 = SMLAD(p, a2, s0);
                s0 = SMLABT(q, b2, s0);
                s1 = SMLAD(q, b2, s1);
                s1 = SMLATB(p, a2, s1);
            }
            o[x] = (int32_t)USAT(s0 >> 4, 31);
            o[x + 1] = (int32_t)USAT(s1 >> 4, 31);
        }
    }
}

// pool2: maxpool 2x2, one channel, 4x4 -> 2x2
static inline void pool2_ch(const int32_t *restrict in, int32_t *restrict out) {
    for (int y = 0; y < 2; y++) {
        const int32_t *r0 = in + 2 * y * 4, *r1 = r0 + 4;
        for (int x = 0; x < 2; x++) {
            int32_t a = r0[2 * x], b = r0[2 * x + 1], c = r1[2 * x], d = r1[2 * x + 1];
            int32_t ab = a > b ? a : b, cd = c > d ? c : d;
            out[y * 2 + x] = ab > cd ? ab : cd;
        }
    }
}

// norm0: ReLU + dynamic power-of-two requantization to 0..127, 320 values
static inline void norm0(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 320; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 320; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

// fc1: linear 320 -> 96, int8 weights
static inline void fc1(const int8_t *restrict in, int32_t *restrict out) {
    const int8_t *w = fc1_w;
    for (int o = 0; o < 96; o++) {
        int32_t sum = 0;
        for (int i = 0; i < 320; i++) sum += (int32_t)*w++ * in[i];
        out[o] = sum;
    }
}

// norm1: ReLU + dynamic power-of-two requantization to 0..127, 96 values
static inline void norm1(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 96; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 96; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

// fc2: linear 96 -> 64, int8 weights
static inline void fc2(const int8_t *restrict in, int32_t *restrict out) {
    const int8_t *w = fc2_w;
    for (int o = 0; o < 64; o++) {
        int32_t sum = 0;
        for (int i = 0; i < 96; i++) sum += (int32_t)*w++ * in[i];
        out[o] = sum;
    }
}

// norm2: ReLU + dynamic power-of-two requantization to 0..127, 64 values
static inline void norm2(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 64; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 64; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

// fc3: linear 64 -> 10, int8 weights
static inline void fc3(const int8_t *restrict in, int32_t *restrict out) {
    const int8_t *w = fc3_w;
    for (int o = 0; o < 10; o++) {
        int32_t sum = 0;
        for (int i = 0; i < 64; i++) sum += (int32_t)*w++ * in[i];
        out[o] = sum;
    }
}

uint32_t ref_infer(const int8_t img[REF_IMG_PIXELS], int32_t logits[REF_N_CLASSES]) {
    PROF_BEGIN();
    widen_img(img);   // counted in the conv1 stage
    for (int c = 0; c < 80; c++) {
        conv1_ch(img16, conv1_kp + 6 * c, ch16_a);
        PROF_STAGE(0);
        dw1_ch(ch16_a, dw1_kp + 6 * c, ch16_b);
        PROF_STAGE(1);
        pool1_ch(ch16_b, ch16_a);
        PROF_STAGE(2);
        dw2_ch(ch16_a, dw2_kp + 6 * c, ch_a);
        PROF_STAGE(3);
        pool2_ch(ch_a, feat + 4 * c);
        PROF_STAGE(4);
    }
    norm0(feat, act);
    fc1(act, acc);
    PROF_STAGE(5);
    norm1(acc, act);
    fc2(act, acc);
    PROF_STAGE(6);
    norm2(acc, act);
    fc3(act, logits);
    PROF_STAGE(7);
    uint32_t best = 0;
    for (uint32_t i = 1; i < 10; i++) if (logits[i] > logits[best]) best = i;
    return best;
}
